import{_ as a,o as i,c as t,aB as o}from"./chunks/framework.DCB2nnuE.js";const h=JSON.parse('{"title":"Welcome","description":"","frontmatter":{"layout":"home","hero":{"name":"Amin Alibakhshi","text":"Personal Academic Page","tagline":"Research, projects, and publications","actions":[{"theme":"brand","text":"Papers","link":"/papers"},{"theme":"alt","text":"GitHub","link":"https://github.com/Aminofa70"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),n={name:"index.md"};function r(s,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="Welcome" tabindex="-1">Welcome <a class="header-anchor" href="#Welcome" aria-label="Permalink to &quot;Welcome {#Welcome}&quot;">​</a></h1><p>I am Amin Alibakhshi.</p><p>This is my personal page for research, projects, and publications.</p><h2 id="About" tabindex="-1">About <a class="header-anchor" href="#About" aria-label="Permalink to &quot;About {#About}&quot;">​</a></h2><p>I have been conducting research since 2016, beginning in the final year of my bachelor’s degree. With nearly eight years of experience in scientific research, I have developed a solid foundation in solid mechanics, computational modeling, and numerical methods, with a strong emphasis on interdisciplinary applications in smart materials and advanced structural analysis.</p><p>My research interests include solid mechanics, biomechanics, artificial neural networks, smart materials, finite element analysis, topology optimization, metamaterials, structural dynamics, and nonlinear vibrations. I am particularly focused on the development of numerical methods for multiphysics problems involving soft and active materials.</p><p>In 2022, I was awarded a prestigious Marie Sklodowska-Curie fellowship to pursue a Ph.D. at Universidad Politécnica de Madrid, Spain, where I am currently working on advanced topology optimization techniques, biomedical modeling, and functionally graded materials.</p><p>During my secondment at the University of Florida, USA. I worked under the supervision of Professor Nam Ho Kim on the topology optimization of functionally graded materials.</p><p>Beyond theoretical and applied research, I am actively involved in scientific software development. I created Julia packages PUPM.jl, which provides tools for topology optimization using the semi-penalized UPM method, GrowthTop.jl bone remodeling driven topology optimization (Growth Method). I have contributed to the development of FEBio.jl, a Julia interface for nonlinear finite element analysis based on the core functionality of the original FEBio software, widely used in biomechanics and computational solid mechanics. Additionally, I contribute to the COMODO-research project in Julia, a tool designed for finite element analysis and mesh generation.</p><h2 id="Papers" tabindex="-1">Papers <a class="header-anchor" href="#Papers" aria-label="Permalink to &quot;Papers {#Papers}&quot;">​</a></h2><p>See my papers here:</p><p><a href="./papers">Papers</a></p><h2 id="GitHub" tabindex="-1">GitHub <a class="header-anchor" href="#GitHub" aria-label="Permalink to &quot;GitHub {#GitHub}&quot;">​</a></h2><p><a href="https://github.com/Aminofa70" target="_blank" rel="noreferrer">View my GitHub</a></p>',14)])])}const u=a(n,[["render",r]]);export{h as __pageData,u as default};
